    task check_output(input [3:0] exp);
        begin
            @(posedge clk);
            #1; // Small delay to sample after clock edge
            if (q !== exp) begin
                $display("Time %0t: Mismatch! Expected q = %0d, Got q = %0d (slowena=%b, reset=%b)", 
                         $time, exp, q, slowena, reset);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        slowena = 0;
        expected_q = 4'd0;

        // Apply reset
        #12;
        if (q !== 4'd0) begin
            $display("Time %0t: Reset error! Expected q = 0, Got q = %0d", $time, q);
            errors = errors + 1;
        end

        // Release reset, slowena low (counter should hold state)
        reset = 0;
        slowena = 0;
        repeat (3) begin
            check_output(4'd0);
        end

        // Enable counting (slowena = 1), count from 0 to 9 and wrap to 0
        slowena = 1;
        for (integer i = 1; i <= 9; i = i + 1) begin
            expected_q = i[3:0];
            check_output(expected_q);
        end

        // Wrap around test: should go from 9 to 0
        expected_q = 4'd0;
        check_output(expected_q);

        // Test pause during counting (slowena toggling)
        slowena = 0;
        check_output(4'd0); // should hold at 0
        check_output(4'd0); // should hold at 0

        slowena = 1;
        expected_q = 4'd1;
        check_output(expected_q);

        slowena = 0;
        check_output(4'd1); // should hold at 1

        slowena = 1;
        expected_q = 4'd2;
        check_output(expected_q);

        // Test synchronous reset while counting
        reset = 1;
        slowena = 1;
        expected_q = 4'd0;
        check_output(expected_q);

        reset = 0;
        expected_q = 4'd1;
        check_output(expected_q);

        // Final evaluation
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
